package com.gomgomapps.math.core;
import java.util.*;import java.math.*;import org.junit.Test;import static org.junit.Assert.*;
public class FractionDivisionDecimalTest {
 @Test public void selectedTerminatingScopeIncludesEighthsZeroWholeAndExactValues(){int count=0;var limits=GlobalCurriculum.limits("england-primary-2021-v1","el_fraction_decimal",6);for(int d:limits.fractionDenominators())for(int n=0;n<=d;n++){Question q=ElementaryBasics.fractionDecimal(Catalog.get("el_fraction_decimal"),n,d);assertTrue(limits.allows(q));assertEquals(Rational.of(n,d),Expression.number(q.answers[0]));HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertTrue(h.step(0).accepts(Integer.toString(n)));assertTrue(h.step(1).accepts(Integer.toString(d)));BigDecimal result=BigDecimal.valueOf(n).divide(BigDecimal.valueOf(d));assertTrue(h.step(h.size()-1).accepts(result.setScale(Math.max(1,result.scale())).toPlainString()));assertFalse(h.step(h.size()-1).accepts(n+"/"+d));count++;}assertEquals(2354,count);Question eighth=ElementaryBasics.fractionDecimal(Catalog.get("el_fraction_decimal"),5,8);assertEquals("0.625",eighth.answers[0]);assertEquals(3,HelpPlan.forQuestion(eighth).size());}
 @Test public void publicDivisionHelpIgnoresHiddenAnswerAndRejectsRecurringDenominators(){Question q=new Question("el_fraction_decimal","7/8의 값을 소수로 나타내세요.","poison","999");HelpPlan h=HelpPlan.forQuestion(q);assertEquals(3,h.size());assertTrue(h.step(0).accepts("7"));assertTrue(h.step(1).accepts("8"));assertEquals("소수 v = n ÷ d = ",h.step(2).before);assertTrue(h.step(2).accepts("0.875"));assertFalse(h.canTransfer());Question bad=new Question("el_fraction_decimal","1/3의 값을 소수로 나타내세요.","","0");DecimalFractionRelations.attach(bad);assertNull(bad.studyGuide);}
 @Test public void selectedGradeLinkAndSupplyPreserveEarlierUnitPartWork(){var pack=GlobalCurriculum.packs("GB").stream().filter(x->x.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade("el_fraction_decimal",6));Generator g=new Generator(new Random(91));List<String> recent=new ArrayList<>();var limits=GlobalCurriculum.limits(pack.id,"el_fraction_decimal",6);for(int i=0;i<150;i++){Question q=g.next("el_fraction_decimal",recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertFalse(HelpPlan.forQuestion(q).canTransfer());}Question old=ElementaryBasics.fractionDecimal(Catalog.get("el_fraction_decimal"),375,1000);HelpPlan h=HelpPlan.forQuestion(old);assertEquals(4,h.size());assertTrue(h.step(2).accepts("0.001"));assertTrue(h.step(3).accepts("0.375"));}
}
